// Nodo "Configuración" del flujo "Secretaria · Vigilar Drive": lo que se toca a mano está aquí.
// Los demás nodos leen estos valores con $('Configuración').first().json.config
// Los SECRETOS no están aquí: el número de destino se lee del entorno de n8n (WHATSAPP_NUMERO_PERMITIDO, definido en el .env)
// y el token de envío va en una credencial de n8n (Header Auth), no aquí.

// Los identificadores (no son secretos) se leen del .env del servidor, así se ponen UNA vez para todos los flujos.
// Si una variable no está en el .env, vale lo que esté escrito aquí abajo.
const delEntorno = (clave, porDefecto) => {
  try {
    return String($env[clave] ?? '').trim() || porDefecto;
  } catch (e) {
    return porDefecto;
  }
};

// === Valores fáciles de cambiar ===
// Project URL de Supabase (Integrations > Data API), sin /rest/v1 al final. No es un secreto.
const SUPABASE_URL = delEntorno('SUPABASE_URL', 'https://TU-PROYECTO.supabase.co');
// Identificador del número de WhatsApp desde el que se envía (WhatsApp > API Setup > Phone number ID). No es un secreto.
const PHONE_NUMBER_ID = delEntorno('WHATSAPP_PHONE_NUMBER_ID', 'TU-PHONE-NUMBER-ID');
// Versión de la API Graph de Meta (la misma que en el flujo "Secretaria · WhatsApp")
const GRAPH_VERSION = 'v26.0';
// ID de la carpeta "Secretaria" de Drive (el mismo CARPETA_RAIZ_ID del flujo "Sincronizar Drive"). Solo se vigila lo que cuelga de ella.
const CARPETA_RAIZ_ID = delEntorno('DRIVE_CARPETA_RAIZ_ID', 'TU-CARPETA-RAIZ');
// Horas desde el último mensaje tuyo durante las que Meta admite texto libre (Meta admite 24 h: margen para no rozar el límite).
// Fuera de ese plazo NO se envía nada (sin plantillas): los cambios quedan anotados y se avisan cuando vuelvas a escribir.
const VENTANA_HORAS = 23;
// Cuántos elementos que han desaparecido del árbol se confirman con Drive en cada pasada (uno de cada carpeta borrada, no uno por archivo).
const LOTE_CONFIRMAR = 40;
// Líneas máximas de un aviso (lo que sobre se avisa en la pasada siguiente)
const MAX_LINEAS = 15;
// ==================================

if (!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(SUPABASE_URL) || SUPABASE_URL.includes('TU-PROYECTO')) {
  throw new Error('Configuración: pon tu Project URL de Supabase en SUPABASE_URL (https://<ref>.supabase.co, sin /rest/v1). Va en el .env del servidor (SUPABASE_URL=…, y después docker compose up -d)');
}
if (!/^\d{8,20}$/.test(PHONE_NUMBER_ID)) {
  throw new Error('Configuración: pon el Phone number ID de WhatsApp en PHONE_NUMBER_ID (solo dígitos). Va en el .env del servidor (WHATSAPP_PHONE_NUMBER_ID=…, y después docker compose up -d)');
}
if (!/^v\d+\.\d+$/.test(GRAPH_VERSION)) {
  throw new Error('Configuración: GRAPH_VERSION debe tener la forma v26.0');
}
if (!/^[A-Za-z0-9_-]{10,}$/.test(CARPETA_RAIZ_ID) || CARPETA_RAIZ_ID.includes('TU-CARPETA')) {
  throw new Error('Configuración: pon el ID de la carpeta "Secretaria" de Drive en CARPETA_RAIZ_ID (solo letras, números, guion y guion bajo). Va en el .env del servidor (DRIVE_CARPETA_RAIZ_ID=…, y después docker compose up -d)');
}
if (!Number.isFinite(VENTANA_HORAS) || VENTANA_HORAS < 1 || VENTANA_HORAS > 24) {
  throw new Error('Configuración: VENTANA_HORAS debe estar entre 1 y 24');
}
if (!Number.isInteger(LOTE_CONFIRMAR) || LOTE_CONFIRMAR < 1 || LOTE_CONFIRMAR > 200) {
  throw new Error('Configuración: LOTE_CONFIRMAR debe estar entre 1 y 200');
}
if (!Number.isInteger(MAX_LINEAS) || MAX_LINEAS < 1 || MAX_LINEAS > 40) {
  throw new Error('Configuración: MAX_LINEAS debe estar entre 1 y 40');
}

return [
  {
    json: {
      config: {
        supabase_url: SUPABASE_URL.replace(/\/+$/, ''),
        phone_number_id: PHONE_NUMBER_ID,
        graph_version: GRAPH_VERSION,
        carpeta_raiz_id: CARPETA_RAIZ_ID,
        ventana_horas: VENTANA_HORAS,
        lote_confirmar: LOTE_CONFIRMAR,
        max_lineas: MAX_LINEAS,
      },
    },
  },
];

// Nodo "Comparar": compara lo que hay AHORA en Drive (cuatro niveles bajo la carpeta raíz) con la foto guardada en la base de datos
// (drive_arbol) y con los archivos que la secretaria tiene registrados (archivos). No escribe nada: arma el plan.
//
// Qué detecta:
//   - carpeta CREADA a mano (la que crea la secretaria lleva appProperties.secretaria = '1' y no cuenta);
//   - carpeta o archivo MOVIDO o RENOMBRADO a mano (un archivo solo si la secretaria lo tiene registrado y el cambio no es suyo:
//     lo que hace «Sincronizar Drive» deja archivos.carpeta_id y archivos.nombre igual que Drive, o el archivo con drive_pendiente);
//   - RESTAURADO de la papelera (estaba eliminado en la foto y vuelve a estar);
//   - lo que HA DESAPARECIDO: se confirma después con Drive (nodo «Confirmar en Drive») si está en la papelera, borrado del todo o
//     solo fuera de lo vigilado. Solo se confirma el elemento de más arriba de cada carpeta borrada (no uno por archivo).
// Las listas de archivos creados a mano NO se avisan (solo quedan en la foto): el aviso es de carpetas y de los archivos de la secretaria.
//
// Seguridad: si Drive devuelve más de una página en algún nivel, o Supabase llega al tope de filas, se PARA con un error sin tocar nada
// (con la lectura incompleta parecería que faltan cosas que sí existen).
//
// Salida: un item por elemento a confirmar (con su URL), o uno inocuo si no hay ninguno. El primero lleva el plan completo.

const config = $('Configuración').first().json.config;
const RAIZ = config.carpeta_raiz_id;
const CARPETA = 'application/vnd.google-apps.folder';
const TOPE_FILAS = 1000; // límite por defecto de Supabase (PostgREST): llegar a él indica lectura truncada
const ahora = new Date().toISOString();

const lee = (nombre) =>
  $(nombre)
    .all()
    .map((i) => i.json);

const foto = lee('Leer foto del árbol').filter((r) => r && typeof r.drive_id === 'string');
const registrados = lee('Leer archivos registrados').filter((r) => r && typeof r.drive_file_id === 'string');
if (foto.length >= TOPE_FILAS || registrados.length >= TOPE_FILAS) {
  throw new Error(`Comparar: Supabase devolvió ${TOPE_FILAS} filas (su límite): la lectura puede estar truncada y no se toca nada. Hay que paginar la lectura.`);
}

// --- Lo que hay ahora en Drive ---
const vivos = new Map();
['Listar nivel 1', 'Listar nivel 2', 'Listar nivel 3', 'Listar nivel 4'].forEach((nodo, i) => {
  const nivel = $(nodo).first().json ?? {};
  if (nivel.nextPageToken) throw new Error(`Comparar: Drive devolvió más de una página en el nivel ${i + 1}: se para sin tocar nada para no dar por borrado lo que sí existe`);
  for (const f of Array.isArray(nivel.files) ? nivel.files : []) {
    if (!f || typeof f.id !== 'string' || typeof f.name !== 'string') continue;
    vivos.set(f.id, {
      id: f.id,
      nombre: f.name,
      tipo: f.mimeType === CARPETA ? 'carpeta' : 'archivo',
      padre_id: Array.isArray(f.parents) && f.parents.length > 0 ? f.parents[0] : null,
      sistema: f.appProperties?.secretaria === '1',
    });
  }
});

const memoRuta = new Map();
function rutaDe(id, profundidad = 0) {
  if (id === RAIZ) return '';
  if (profundidad > 8) return null;
  if (memoRuta.has(id)) return memoRuta.get(id);
  const v = vivos.get(id);
  if (!v) return null;
  const padre = v.padre_id === RAIZ || v.padre_id === null ? '' : rutaDe(v.padre_id, profundidad + 1);
  const ruta = padre === null ? null : padre ? `${padre}/${v.nombre}` : v.nombre;
  memoRuta.set(id, ruta);
  return ruta;
}
for (const v of vivos.values()) v.ruta = rutaDe(v.id);
for (const [id, v] of [...vivos]) if (v.ruta === null) vivos.delete(id); // sin ruta calculable (huérfano): no se vigila

const fila = (v, origen, extra = {}) => ({
  drive_id: v.id,
  tipo: v.tipo,
  nombre: v.nombre,
  padre_id: v.padre_id,
  ruta: v.ruta,
  origen,
  visto_at: ahora,
  eliminado_at: null,
  updated_at: ahora,
  ...extra,
});

// --- Primera vez: se guarda la foto sin avisar de nada ---
if (foto.length === 0) {
  const plan = { modo: 'base', ahora, upserts: [...vivos.values()].map((v) => fila(v, 'base')), eventos: [], archivos_manual: [], restaurados_archivos: [], restaurados_carpetas: [], silenciosos: [], candidatos: [], pospuestos: 0 };
  return [{ json: { inerte: true, url: `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(RAIZ)}?fields=id&supportsAllDrives=true`, plan } }];
}

const S = new Map(foto.filter((r) => r.eliminado_at == null).map((r) => [r.drive_id, r]));
const E = new Map(foto.filter((r) => r.eliminado_at != null).map((r) => [r.drive_id, r]));
const reg = new Map(registrados.filter((r) => r.eliminado_at == null).map((r) => [r.drive_file_id, r]));

const upserts = [];
const eventos = [];
const archivosManual = [];
const restauradosArchivos = [];
const restauradosCarpetas = [];
const evento = (tipo, v, antes, despues, detalle, previa) => ({ tipo, drive_id: v.id, nombre: v.nombre, ruta_antes: antes, ruta_despues: despues, detalle, previa });

// --- Lo nuevo, lo cambiado y lo recuperado ---
const nuevosManuales = new Set();
const restaurados = new Set();
for (const v of vivos.values()) {
  const s = S.get(v.id);
  const e = E.get(v.id);
  if (!s && e) restaurados.add(v.id);
  else if (!s) {
    const esSistema = v.tipo === 'carpeta' ? v.sistema : reg.has(v.id);
    upserts.push(fila(v, esSistema ? 'sistema' : 'manual'));
    if (!esSistema && v.tipo === 'carpeta') nuevosManuales.add(v.id);
  }
}

// Creadas a mano: se avisa de la de más arriba de cada rama, con lo que cuelga de ella
const hijosNuevos = new Map();
for (const id of nuevosManuales) {
  const v = vivos.get(id);
  if (!hijosNuevos.has(v.padre_id)) hijosNuevos.set(v.padre_id, []);
  hijosNuevos.get(v.padre_id).push(id);
}
const archivosNuevosPorPadre = new Map();
for (const v of vivos.values()) {
  if (v.tipo === 'archivo' && !S.has(v.id) && !E.has(v.id)) archivosNuevosPorPadre.set(v.padre_id, (archivosNuevosPorPadre.get(v.padre_id) ?? 0) + 1);
}
function contarNuevo(id) {
  let carpetas = 0;
  let archivos = archivosNuevosPorPadre.get(id) ?? 0;
  for (const h of hijosNuevos.get(id) ?? []) {
    const c = contarNuevo(h);
    carpetas += 1 + c.carpetas;
    archivos += c.archivos;
  }
  return { carpetas, archivos };
}
for (const id of nuevosManuales) {
  const v = vivos.get(id);
  if (nuevosManuales.has(v.padre_id)) continue;
  const c = contarNuevo(id);
  eventos.push(evento('carpeta_creada', v, null, v.ruta, { subcarpetas: c.carpetas, archivos: c.archivos }, 'nueva'));
}

// Recuperadas de la papelera: se avisa de la de más arriba; se reactivan los archivos y carpetas pedidas que dependían de ellas
for (const id of restaurados) {
  const v = vivos.get(id);
  const e = E.get(id);
  upserts.push(fila(v, e.origen ?? 'base'));
  if (v.tipo === 'archivo' && registrados.some((r) => r.drive_file_id === id)) restauradosArchivos.push(id);
  if (v.tipo === 'carpeta') restauradosCarpetas.push(id);
  if (restaurados.has(v.padre_id)) continue;
  if (v.tipo === 'carpeta') eventos.push(evento('carpeta_restaurada', v, null, v.ruta, {}, e.eliminado_at));
  else if (registrados.some((r) => r.drive_file_id === id)) eventos.push(evento('archivo_restaurado', v, null, v.ruta, {}, e.eliminado_at));
}
// Archivos registrados que estaban eliminados en la base y siguen vivos (p. ej. la foto se restauró sin pasar por la foto del árbol)
for (const r of registrados) if (r.eliminado_at != null && vivos.has(r.drive_file_id) && !restaurados.has(r.drive_file_id)) restauradosArchivos.push(r.drive_file_id);

// --- Movidos y renombrados ---
for (const v of vivos.values()) {
  const s = S.get(v.id);
  if (!s) continue;
  const movido = s.padre_id !== v.padre_id;
  const renombrado = s.nombre !== v.nombre;
  const rutaCambia = s.ruta !== v.ruta;
  if (!movido && !renombrado && !rutaCambia) continue;
  upserts.push(fila(v, s.origen ?? 'base'));
  if (!movido && !renombrado) continue; // solo cambia la ruta porque se movió o renombró una carpeta de más arriba

  if (v.tipo === 'carpeta') {
    eventos.push(evento(movido ? 'carpeta_movida' : 'carpeta_renombrada', v, s.ruta, v.ruta, { renombrada: movido && renombrado, nombre_antes: s.nombre }, s.updated_at));
    continue;
  }
  const a = reg.get(v.id);
  if (!a) continue; // un archivo que la secretaria no tiene registrado: solo cambia la foto
  const loHizoElSistema = a.drive_pendiente === true || (a.nombre === v.nombre && a.carpeta_id === v.padre_id);
  if (loHizoElSistema) continue;
  archivosManual.push({ drive_file_id: v.id, ...(movido ? { carpeta_id: v.padre_id } : {}), ...(renombrado ? { nombre: v.nombre } : {}) });
  eventos.push(evento(movido ? 'archivo_movido' : 'archivo_renombrado', v, s.ruta, v.ruta, { renombrada: movido && renombrado, nombre_antes: s.nombre }, s.updated_at));
}

// --- Lo que ha desaparecido ---
const desaparecidos = new Set([...S.keys()].filter((id) => !vivos.has(id)));
const hijosFoto = new Map();
for (const r of S.values()) {
  if (!hijosFoto.has(r.padre_id)) hijosFoto.set(r.padre_id, []);
  hijosFoto.get(r.padre_id).push(r);
}
function bajoDesaparecido(raiz) {
  const filas = [];
  const pila = [...(hijosFoto.get(raiz.drive_id) ?? [])];
  while (pila.length) {
    const r = pila.pop();
    if (!desaparecidos.has(r.drive_id)) continue;
    filas.push(r);
    pila.push(...(hijosFoto.get(r.drive_id) ?? []));
  }
  return filas;
}
const cima = [...desaparecidos].map((id) => S.get(id)).filter((r) => !desaparecidos.has(r.padre_id));
const candidatos = [];
const silenciosos = []; // archivos sin registrar que faltan: solo se marcan en la foto
for (const r of cima.sort((a, b) => String(a.ruta).localeCompare(String(b.ruta), 'es'))) {
  const debajo = bajoDesaparecido(r);
  const todos = [r, ...debajo];
  const registrada = r.tipo === 'archivo' && reg.has(r.drive_id);
  if (r.tipo === 'archivo' && !registrada) {
    silenciosos.push(fila({ id: r.drive_id, nombre: r.nombre, tipo: r.tipo, padre_id: r.padre_id, ruta: r.ruta }, r.origen ?? 'base', { eliminado_at: ahora, visto_at: r.visto_at }));
    continue;
  }
  candidatos.push({
    drive_id: r.drive_id,
    tipo: r.tipo,
    nombre: r.nombre,
    ruta: r.ruta,
    previa: r.updated_at,
    filas: todos.map((x) => ({ drive_id: x.drive_id, tipo: x.tipo, nombre: x.nombre, padre_id: x.padre_id, ruta: x.ruta, origen: x.origen ?? 'base', visto_at: x.visto_at ?? ahora })),
    archivos_registrados: todos.filter((x) => x.tipo === 'archivo' && reg.has(x.drive_id)).map((x) => x.drive_id),
    carpetas: todos.filter((x) => x.tipo === 'carpeta').map((x) => x.drive_id),
    n_archivos: todos.filter((x) => x.tipo === 'archivo').length,
    n_subcarpetas: todos.filter((x) => x.tipo === 'carpeta' && x.drive_id !== r.drive_id).length,
  });
}
const aConfirmar = candidatos.slice(0, config.lote_confirmar);
const plan = {
  modo: 'normal',
  ahora,
  upserts,
  eventos,
  archivos_manual: archivosManual,
  restaurados_archivos: restauradosArchivos,
  restaurados_carpetas: restauradosCarpetas,
  silenciosos,
  candidatos: aConfirmar,
  pospuestos: candidatos.length - aConfirmar.length,
};

const urlComprobar = (id) => `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(id)}?fields=${encodeURIComponent('id,name,trashed,parents')}&supportsAllDrives=true`;
if (aConfirmar.length === 0) {
  return [{ json: { inerte: true, url: `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(RAIZ)}?fields=id&supportsAllDrives=true`, plan } }];
}
return aConfirmar.map((c, i) => ({ json: { inerte: false, drive_id: c.drive_id, url: urlComprobar(c.drive_id), ...(i === 0 ? { plan } : {}) } }));

// Nodo "Decidir": junta el plan de "Comparar" con lo que Drive ha respondido sobre lo que desapareció y arma las escrituras en Supabase.
//
// Para cada elemento desaparecido ("Confirmar en Drive" pregunta por él):
//   404                      borrado del todo (de la papelera también)  -> eliminado
//   200 y trashed = true     en la papelera                             -> eliminado
//   200 y trashed = false    sigue existiendo pero fuera de lo vigilado -> movido fuera (los archivos y carpetas NO se marcan eliminados)
//   otra cosa (403, 5xx…)    sin certeza -> no se hace nada y se reintenta en la pasada siguiente
// Lo eliminado se marca en la foto (drive_arbol), en los archivos registrados (archivos.eliminado_at) y en las carpetas pedidas
// (carpetas_pedidas.eliminada_at). Las filas NO se borran. Todo queda en registro_drive, con una clave única por cambio
// (tipo + id de Drive + estado anterior de la foto): repetir el flujo no duplica nada.
//
// Orden de las escrituras: primero el registro y las marcas, y LA FOTO LA ÚLTIMA. Si algo falla por el camino, la foto sigue siendo la
// de antes y en la pasada siguiente se detecta lo mismo (la clave única evita duplicar el registro).

const config = $('Configuración').first().json.config;
const base = `${config.supabase_url}/rest/v1`;
const plan = $('Comparar').first().json.plan;
const respuestas = $input.all().map((i) => i.json);
const ahora = plan.ahora;

const eventos = [...plan.eventos];
const upserts = [...plan.upserts, ...plan.silenciosos];
const archivosEliminar = [];
const carpetasEliminar = [];

(plan.candidatos ?? []).forEach((c, i) => {
  const r = respuestas[i];
  const estado = r?.statusCode;
  const trashed = r?.body?.trashed === true;
  let veredicto = null;
  if (estado === 404) veredicto = 'borrado';
  else if (estado >= 200 && estado < 300 && trashed) veredicto = 'papelera';
  else if (estado >= 200 && estado < 300) veredicto = 'fuera';
  if (veredicto === null) return;

  for (const f of c.filas) upserts.push({ ...f, updated_at: ahora, eliminado_at: ahora });
  const v = { id: c.drive_id, nombre: c.nombre };
  if (veredicto === 'fuera') {
    eventos.push({ tipo: c.tipo === 'carpeta' ? 'carpeta_movida' : 'archivo_movido', drive_id: v.id, nombre: v.nombre, ruta_antes: c.ruta, ruta_despues: null, detalle: { fuera: true, archivos: c.n_archivos, subcarpetas: c.n_subcarpetas }, previa: c.previa });
    return;
  }
  archivosEliminar.push(...c.archivos_registrados);
  carpetasEliminar.push(...c.carpetas);
  eventos.push({
    tipo: c.tipo === 'carpeta' ? 'carpeta_eliminada' : 'archivo_eliminado',
    drive_id: v.id,
    nombre: v.nombre,
    ruta_antes: c.ruta,
    ruta_despues: null,
    detalle: { archivos: c.n_archivos, subcarpetas: c.n_subcarpetas, definitivo: veredicto === 'borrado' },
    previa: c.previa,
  });
});

// --- Escrituras ---
const escrituras = [];
const escribir = (etiqueta, metodo, ruta, cuerpo, prefer) => escrituras.push({ etiqueta, metodo, url: `${base}${ruta}`, cuerpo, prefer });
const enLotes = (lista, n) => {
  const lotes = [];
  for (let i = 0; i < lista.length; i += n) lotes.push(lista.slice(i, i + n));
  return lotes;
};
const unicos = (lista) => [...new Set(lista)];
const lista = (ids) => `in.(${ids.map(encodeURIComponent).join(',')})`;

if (eventos.length > 0) {
  const vistas = new Set();
  const filas = [];
  for (const e of eventos) {
    const clave = `${e.tipo}|${e.drive_id}|${e.previa ?? 'nuevo'}`;
    if (vistas.has(clave)) continue;
    vistas.add(clave);
    filas.push({ tipo: e.tipo, drive_id: e.drive_id, nombre: e.nombre, ruta_antes: e.ruta_antes, ruta_despues: e.ruta_despues, detalle: e.detalle ?? {}, clave });
  }
  escribir(`registrar ${filas.length} cambio(s)`, 'POST', '/registro_drive?on_conflict=clave', filas, 'resolution=ignore-duplicates,return=minimal');
}
for (const lote of enLotes(unicos(archivosEliminar), 80)) {
  escribir('archivos eliminados', 'PATCH', `/archivos?drive_file_id=${lista(lote)}&eliminado_at=is.null`, { eliminado_at: ahora, drive_pendiente: false }, 'return=minimal');
}
for (const lote of enLotes(unicos(plan.restaurados_archivos), 80)) {
  escribir('archivos recuperados', 'PATCH', `/archivos?drive_file_id=${lista(lote)}`, { eliminado_at: null }, 'return=minimal');
}
for (const a of plan.archivos_manual) {
  const { drive_file_id: id, ...cambios } = a;
  escribir(`archivo cambiado a mano ${id}`, 'PATCH', `/archivos?drive_file_id=eq.${encodeURIComponent(id)}`, { ...cambios, vigilado_at: ahora }, 'return=minimal');
}
for (const lote of enLotes(unicos(carpetasEliminar), 80)) {
  escribir('carpetas pedidas eliminadas', 'PATCH', `/carpetas_pedidas?carpeta_id=${lista(lote)}&eliminada_at=is.null`, { eliminada_at: ahora, drive_pendiente: false }, 'return=minimal');
}
for (const lote of enLotes(unicos(plan.restaurados_carpetas), 80)) {
  escribir('carpetas pedidas recuperadas', 'PATCH', `/carpetas_pedidas?carpeta_id=${lista(lote)}`, { eliminada_at: null }, 'return=minimal');
}
// La foto, la última. Sin dos filas con el mismo id en una petición (Postgres lo rechaza); gana la última.
const porId = new Map();
for (const f of upserts) porId.set(f.drive_id, f);
for (const lote of enLotes([...porId.values()], 300)) {
  escribir(`foto del árbol (${lote.length})`, 'POST', '/drive_arbol?on_conflict=drive_id', lote, 'resolution=merge-duplicates,return=minimal');
}

if (escrituras.length === 0) {
  // Nada que escribir: una escritura inocua para que el flujo siga hacia los avisos pendientes
  // (un PATCH sobre un id que no existe: no toca ninguna fila)
  return [{ json: { etiqueta: 'sin cambios', metodo: 'PATCH', url: `${base}/registro_drive?id=eq.00000000-0000-0000-0000-000000000000`, cuerpo: {}, prefer: 'return=minimal' } }];
}
return escrituras.map((e) => ({ json: e }));

// Nodo "Redactar aviso": construye UN mensaje de WhatsApp con los cambios de Drive que aún no se han avisado (registro_drive con
// notificado_at nulo) y el cuerpo exacto de la petición a Meta, más los ids para marcarlos como avisados después (solo si Meta acepta).
//
// - Solo como texto libre y solo si la ventana de 24 h de Meta sigue abierta (el último mensaje TUYO es de hace menos de VENTANA_HORAS).
//   Si está cerrada devuelve [] y no se envía nada: no hay plantillas. Los cambios quedan anotados y se avisan cuando vuelvas a escribir.
// - Se redacta con código, nunca con el modelo. Máximo MAX_LINEAS líneas; el resto sale en la pasada siguiente.

const config = $('Configuración').first().json.config;
const LIMITE_MENSAJE = 3800;
const limpiar = (s) => String(s ?? '').replace(/[*_~`]/g, '').replace(/\s+/g, ' ').trim();
const ruta = (r) => limpiar(r) || '(raíz)';
const plural = (n, uno, varios) => `${n} ${n === 1 ? uno : varios}`;

const filas = $('Leer sin avisar')
  .all()
  .map((i) => i.json)
  .filter((r) => r && typeof r.id === 'string' && typeof r.tipo === 'string' && typeof r.nombre === 'string')
  .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
if (filas.length === 0) return [];

const ultimo = $('Leer último mensaje')
  .all()
  .map((x) => x.json)
  .filter((r) => r && typeof r.created_at === 'string')
  .map((r) => new Date(r.created_at))
  .filter((d) => !Number.isNaN(d.getTime()))[0];
const ahora = new Date();
const ventanaAbierta = Boolean(ultimo) && ahora.getTime() - ultimo.getTime() < config.ventana_horas * 3600 * 1000;
if (!ventanaAbierta) return [];

const para = String($env.WHATSAPP_NUMERO_PERMITIDO ?? '').replace(/\D/g, '');
if (!para) throw new Error('Redactar aviso: falta WHATSAPP_NUMERO_PERMITIDO en el entorno de n8n');

function cuentas(d) {
  const partes = [];
  if (Number(d?.archivos) > 0) partes.push(plural(Number(d.archivos), 'archivo', 'archivos'));
  if (Number(d?.subcarpetas) > 0) partes.push(plural(Number(d.subcarpetas), 'subcarpeta', 'subcarpetas'));
  return partes.length > 0 ? ` (${partes.join(' y ')})` : '';
}

function linea(r) {
  const d = r.detalle ?? {};
  const antes = ruta(r.ruta_antes);
  const despues = ruta(r.ruta_despues);
  const nombre = limpiar(r.nombre);
  switch (r.tipo) {
    case 'carpeta_creada':
      return `📁 Creaste la carpeta «${despues}»${cuentas(d)}.`;
    case 'carpeta_eliminada':
      return `🗑️ Borraste la carpeta «${antes}»${cuentas(d)}${d.definitivo ? ', definitivamente' : ', está en la papelera'}.`;
    case 'carpeta_movida':
      if (d.fuera) return `📤 Sacaste la carpeta «${antes}» de la zona que vigilo${cuentas(d)}.`;
      return `↪️ Moviste la carpeta «${antes}» a «${despues}»${d.renombrada ? ` y la renombraste a «${nombre}»` : ''}.`;
    case 'carpeta_renombrada':
      return `✏️ Renombraste la carpeta «${antes}» a «${nombre}».`;
    case 'carpeta_restaurada':
      return `♻️ Recuperaste la carpeta «${despues}» de la papelera.`;
    case 'archivo_eliminado':
      return `🗑️ Borraste el archivo «${antes}»${d.definitivo ? ', definitivamente' : ', está en la papelera'}.`;
    case 'archivo_movido':
      if (d.fuera) return `📤 Sacaste el archivo «${antes}» de la zona que vigilo.`;
      return `↪️ Moviste el archivo «${antes}» a «${despues}»${d.renombrada ? ` y lo renombraste a «${nombre}»` : ''}.`;
    case 'archivo_renombrado':
      return `✏️ Renombraste el archivo «${antes}» a «${nombre}».`;
    case 'archivo_restaurado':
      return `♻️ Recuperaste el archivo «${despues}» de la papelera.`;
    default:
      return `Cambio en Drive: «${nombre}».`;
  }
}

const incluidas = filas.slice(0, config.max_lineas);
const lineas = incluidas.map(linea);
let texto;
if (lineas.length === 1) {
  texto = `${lineas[0]} Lo he anotado.`;
} else {
  texto = `*Cambios en Drive*\n${lineas.map((l) => `• ${l}`).join('\n')}\nLos he anotado todos.`;
}
const sobran = filas.length - incluidas.length;
if (sobran > 0) texto += `\n… y ${sobran} más (te los digo en el próximo aviso).`;
if (texto.length > LIMITE_MENSAJE) texto = `${texto.slice(0, LIMITE_MENSAJE - 1).trimEnd()}…`;

return [
  {
    json: {
      cuerpo: { messaging_product: 'whatsapp', recipient_type: 'individual', to: para, type: 'text', text: { preview_url: false, body: texto } },
      texto,
      ids: incluidas.map((r) => r.id),
      marca: { notificado_at: ahora.toISOString() },
    },
  },
];
